spec.setup_code:
var geometry = new api.THREE.BoxGeometry(1, 1, 1);
                var material = new api.THREE.MeshPhongMaterial({ color: 0xE8593C });
                var cube = new api.THREE.Mesh(geometry, material);
                api.group.add(cube);
                return {
                  update: function(t) {
                    cube.rotation.x = t * 0.02;
                    cube.rotation.y = t * 0.03;
                  }
                };

return {
                  draw: function(ctx, W, H, t, dt) {
                    ctx.fillStyle = '#F5F0E8';
                    ctx.fillRect(0, 0, W, H);
                    var cx = W/2, cy = H/2;
                    var R = Math.min(W, H) * 0.35;
                    ctx.strokeStyle = '#CFC7B8';
                    for (var ring = 1; ring <= 3; ring++) {
                      ctx.beginPath();
                      ctx.arc(cx, cy, R * ring / 3, 0, Math.PI * 2);
                      ctx.stroke();
                    }
                    var theta = t * 0.03;
                    var r = R;
                    var x = cx + r * Math.cos(theta);
                    var y = cy - r * Math.sin(theta);
                    ctx.strokeStyle = '#8A8272';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.moveTo(cx, cy);
                    ctx.lineTo(x, y);
                    ctx.stroke();
                    ctx.strokeStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(cx, cy, 24, 0, -theta, true);
                    ctx.stroke();
                    ctx.fillStyle = '#E8593C';
                    ctx.beginPath();
                    ctx.arc(x, y, 8, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.beginPath();
                    ctx.arc(cx, cy, 4, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.fillStyle = '#333';
                    ctx.font = '14px sans-serif';
                    ctx.fillText('r = ' + Math.round(r), cx + 10, cy - 10);
                    ctx.fillText('\u03B8 = ' + Math.round(theta * 180 / Math.PI % 360) + '\u00B0', x + 10, y);
                  }
                };
